<script setup lang="ts">
import {computed,onMounted,ref} from "vue";import {useRoute} from "vue-router";import {supabase} from "../stores/auth.store";
const route=useRoute(),token=computed(()=>String(route.params.token||"")),data=ref<any>(null),loading=ref(true),error=ref(""),notice=ref(""),signer=ref(""),canvas=ref<HTMLCanvasElement|null>(null),active=ref(""),busy=ref(false);let drawing=false,ink=false;
function pos(e:PointerEvent){const r=canvas.value!.getBoundingClientRect();return{x:(e.clientX-r.left)*canvas.value!.width/r.width,y:(e.clientY-r.top)*canvas.value!.height/r.height};}
function down(e:PointerEvent){if(!canvas.value)return;drawing=true;canvas.value.setPointerCapture(e.pointerId);const p=pos(e);canvas.value.getContext("2d")!.beginPath();canvas.value.getContext("2d")!.moveTo(p.x,p.y);}
function move(e:PointerEvent){if(!drawing||!canvas.value)return;const p=pos(e),c=canvas.value.getContext("2d")!;c.lineWidth=3;c.lineCap="round";c.strokeStyle="#14213d";c.lineTo(p.x,p.y);c.stroke();ink=true;}
function clear(){const c=canvas.value?.getContext("2d");if(c&&canvas.value)c.clearRect(0,0,canvas.value.width,canvas.value.height);ink=false;}
async function load(){loading.value=true;error.value="";try{if(!supabase)throw Error("الخدمة غير مهيأة");const {data:d,error:e}=await supabase.rpc("client_portal_get",{p_token:token.value});if(e)throw e;data.value=d;}catch(e){error.value=e instanceof Error?e.message:"الرابط غير صالح أو منتهي";}finally{loading.value=false;}}
async function sign(){if(!supabase||!active.value||!canvas.value||!ink||signer.value.trim().length<2){error.value="أدخل اسمك وارسم التوقيع أولاً.";return;}busy.value=true;try{const {error:e}=await supabase.rpc("client_portal_sign",{p_token:token.value,p_invoice_id:active.value,p_signer_name:signer.value.trim(),p_signature_data_url:canvas.value.toDataURL("image/png")});if(e)throw e;notice.value="تم تسجيل التوقيع.";active.value="";clear();await load();}catch(e){error.value=e instanceof Error?e.message:"تعذر تسجيل التوقيع";}finally{busy.value=false;}}
const money=(v:number)=>new Intl.NumberFormat("ar-DZ",{style:"currency",currency:data.value?.company?.currency_code||"DZD"}).format(Number(v)||0);
onMounted(()=>void load());
</script>
<template><main class="min-h-screen bg-slate-50 px-4 py-8 text-slate-800"><div class="mx-auto max-w-5xl space-y-6"><header class="rounded-3xl bg-slate-900 p-7 text-white"><p class="text-sm text-slate-300">بوابة العملاء الآمنة</p><h1 class="mt-2 text-2xl font-bold">{{data?.company?.name||"بوابة العميل"}}</h1><p v-if="data?.client" class="mt-2 text-slate-300">مرحباً {{data.client.name}}، هذه فواتيرك.</p></header><div v-if="loading" class="panel p-8 text-center">جارٍ التحقق من الرابط…</div><div v-else-if="error&&!data" class="panel p-8 text-center text-red-700">{{error}}</div><template v-else-if="data"><p v-if="error" role="alert" class="rounded-xl bg-red-50 p-3 text-red-700">{{error}}</p><p v-if="notice" role="status" class="rounded-xl bg-emerald-50 p-3 text-emerald-700">{{notice}}</p><article v-for="i in data.invoices" :key="i.id" class="panel space-y-4 p-5"><header class="flex flex-wrap justify-between gap-2"><div><p class="text-xs text-slate-500">فاتورة</p><h2 class="text-xl font-bold">{{i.invoice_number}}</h2><p class="text-sm text-slate-500">{{i.issue_date}} · الاستحقاق {{i.due_date||"—"}}</p></div><span class="rounded-full bg-brand-50 px-3 py-2 text-sm text-brand-700">{{i.status}}</span></header><div class="overflow-x-auto"><table class="w-full min-w-[520px] text-right text-sm"><thead class="bg-slate-50"><tr><th class="p-3">الوصف</th><th class="p-3">الكمية</th><th class="p-3">السعر</th><th class="p-3">TVA</th><th class="p-3">الإجمالي</th></tr></thead><tbody class="divide-y"><tr v-for="(x,n) in i.items" :key="n"><td class="p-3">{{x.description}}</td><td class="p-3">{{x.quantity}}</td><td class="p-3">{{money(x.unit_price)}}</td><td class="p-3">{{x.tva_rate}}%</td><td class="p-3">{{money(x.line_subtotal+x.line_tax)}}</td></tr></tbody></table></div><div class="ml-auto max-w-sm space-y-2 rounded-xl bg-slate-50 p-4 text-sm"><p class="flex justify-between"><span>HT</span><b>{{money(i.subtotal)}}</b></p><p class="flex justify-between"><span>TVA</span><b>{{money(i.tax_total)}}</b></p><p class="flex justify-between"><span>TTC</span><b>{{money(i.total)}}</b></p><p class="flex justify-between text-emerald-700"><span>المدفوع</span><b>{{money(i.paid_amount)}}</b></p><p class="flex justify-between border-t pt-2 font-bold"><span>المتبقي</span><b>{{money(i.total-i.paid_amount)}}</b></p></div><div v-if="i.payments?.length" class="text-sm"><b>الدفعات</b><p v-for="(p,n) in i.payments" :key="n" class="flex justify-between border-b py-2"><span>{{p.payment_date}} · {{p.payment_method}}</span><b>{{money(p.amount)}}</b></p></div><p v-if="i.signed" class="rounded-xl bg-emerald-50 p-3 text-emerald-700">تم توقيع هذه الفاتورة.</p><button v-else class="secondary-button" @click="active=i.id;clear()">التوقيع الإلكتروني</button></article><section v-if="active" class="panel space-y-3 p-5"><h2 class="font-bold">اعتماد الفاتورة</h2><input v-model="signer" class="form-input" placeholder="الاسم الكامل للموقّع"/><canvas ref="canvas" width="900" height="220" class="w-full touch-none rounded-xl border border-dashed bg-white" @pointerdown="down" @pointermove="move" @pointerup="drawing=false" @pointercancel="drawing=false"/><div class="flex justify-end gap-2"><button class="secondary-button" @click="clear">مسح</button><button class="secondary-button" @click="active=''">إلغاء</button><button class="primary-button" :disabled="busy" @click="sign">تأكيد التوقيع</button></div></section><p v-if="!data.invoices.length" class="panel p-8 text-center text-slate-500">لا توجد فواتير متاحة.</p></template><footer class="text-center text-xs text-slate-400">هذا الرابط خاص بالعميل، لا تشاركه.</footer></div></main></template>